begin
  delete from auth.users where email like '%@saafsnap.demo';

  for u in select * from (values
    ('n_ganga', 'greenganga@saafsnap.demo', 'Green Ganga Collective', 'ngo', '{"name": "Green Ganga Collective", "regId": "NGO/WB/2019/0231", "city": "Kolkata", "color": "#0ea5e9", "icon": "waves"}'::jsonb),
    ('n_streets', 'streets@saafsnap.demo', 'Clean Streets Kolkata', 'ngo', '{"name": "Clean Streets Kolkata", "regId": "NGO/WB/2020/0540", "city": "Kolkata", "color": "#f59e0b", "icon": "sparkles"}'::jsonb),
    ('c_ananya', 'citizen@saafsnap.demo', 'Ananya Roy', 'citizen', null::jsonb),
    ('c_rahul', 'rahul@saafsnap.demo', 'Rahul Das', 'citizen', null::jsonb),
    ('c_imran', 'imran@saafsnap.demo', 'Imran Sheikh', 'citizen', null::jsonb),
    ('c_priya', 'priya@saafsnap.demo', 'Priya Nair', 'citizen', null::jsonb)
  ) as t(key, email, name, role, org)
  loop
    uid := gen_random_uuid();
    insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, email_change, email_change_token_new, recovery_token)
    values ('00000000-0000-0000-0000-000000000000', uid, 'authenticated', 'authenticated', u.email,
      extensions.crypt(gen_random_uuid()::text, extensions.gen_salt('bf')), now(),
      '{"provider":"email","providers":["email"]}', jsonb_build_object('name', u.name), now(), now(), '', '', '', '');
    insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    values (gen_random_uuid(), uid, uid::text, jsonb_build_object('sub', uid::text, 'email', u.email, 'email_verified', true), 'email', now(), now(), now());
    update public.profiles set role = u.role, status = 'active', org = u.org where id = uid;
    ids := ids || jsonb_build_object(u.key, uid::text);
  end loop;

  for k in select jsonb_object_keys(ids) loop
    data := replace(data, '@@' || k || '@@', ids ->> k);
  end loop;

  insert into public.reports (created_by, created_at, photo, lat, lng, landmark, ward, department, ai,
    seen_by, seen_extra, likes, status, timeline, cleanup, attempts)
  select
    (e ->> 'createdBy')::uuid,
    to_timestamp(((e ->> 'createdAt')::bigint + delta) / 1000.0),
    e ->> 'photo',
    (e -> 'location' ->> 'lat')::float8,
    (e -> 'location' ->> 'lng')::float8,
    e ->> 'landmark',
    (e ->> 'ward')::int,
    e ->> 'department',
    e -> 'ai',
    array(select jsonb_array_elements_text(e -> 'seenBy'))::uuid[],
    (e ->> 'seenExtra')::int,
    array(select jsonb_array_elements_text(e -> 'likes'))::uuid[],
    e ->> 'status',
    (select jsonb_agg(t || jsonb_build_object('at', (t ->> 'at')::bigint + delta)) from jsonb_array_elements(e -> 'timeline') t),
    case when e -> 'cleanup' = 'null'::jsonb then null
         else jsonb_set(e -> 'cleanup', '{at}', to_jsonb((e -> 'cleanup' ->> 'at')::bigint + delta)) end,
    '[]'::jsonb
  from jsonb_array_elements(data::jsonb) e;
end $$;

select
  (select count(*) from auth.users where email like '%@saafsnap.demo') as showcase_accounts,
  (select count(*) from public.reports) as reports,
  (select count(*) from public.reports where status = 'cleaned') as cleaned;
